import { useFBX } from "@react-three/drei";
import { useEffect } from "react";
import * as THREE from "three";

export default function FBXModel({ castShadow = true, receiveShadow = true }) {
  const model = useFBX("/models/八王子30.fbx");

  useEffect(() => {
    if (model) {
      model.scale.set(0.5, 0.5, 0.5);

      model.traverse((child) => {
        if (child.isMesh) {
          child.castShadow = castShadow;
          child.receiveShadow = receiveShadow;

          if (child.material) {
            // Clone material to avoid shared material issues
            child.material = child.material.clone();
            child.material.needsUpdate = true;

            // Smooth shading
            child.material.flatShading = false;

            // Better shadow rendering
            child.material.shadowSide = THREE.FrontSide;

            // Optional: Adjust material properties
            if (child.material.roughness !== undefined) {
              child.material.roughness = Math.max(
                0.7,
                child.material.roughness
              );
            }
            if (child.material.metalness !== undefined) {
              child.material.metalness = Math.min(
                0.3,
                child.material.metalness
              );
            }
          }

          // Ensure geometry has proper normals
          if (child.geometry) {
            child.geometry.computeVertexNormals();
          }
        }
      });
    }
  }, [model, castShadow, receiveShadow]);

  return <primitive object={model} />;
}
