import { Canvas, useThree } from "@react-three/fiber";
import {
  OrbitControls,
  Environment,
  ContactShadows,
  Sky,
} from "@react-three/drei";
import { useEffect, useRef, useState } from "react";
import Model from "./Model";
import One from "./OneFloor";
import Two from "./TwoFloor";
import Three from "./ThreeFloor";
import * as THREE from "three";

/* 🔹 Camera setup */
function CameraSetup() {
  const { camera } = useThree();

  useEffect(() => {
    camera.position.set(40, 15, -40);
    camera.lookAt(20, 10, -15);
  }, [camera]);

  return null;
}

/* 🔹 Enhanced Orbit controls with smooth animations */
function Controls() {
  const controls = useRef();

  useEffect(() => {
    if (controls.current) {
      controls.current.target.set(10, 3, -15);
      controls.current.update();
    }
  }, []);

  return (
    <OrbitControls
      ref={controls}
      makeDefault
      enableDamping
      dampingFactor={0.05}
      enableZoom={true}
      enablePan={true}
      enableRotate={true}
      minDistance={5}
      maxDistance={80}
      maxPolarAngle={Math.PI / 2.1}
      minPolarAngle={Math.PI / 6}
      // Touch controls: 1 finger rotate, 2 fingers pan+zoom
      touches={{
        ONE: THREE.TOUCH.ROTATE, // 1 finger = rotate
        TWO: THREE.TOUCH.DOLLY_PAN, // 2 fingers = pinch zoom + pan
      }}
      zoomSpeed={1.0}
      panSpeed={0.8}
      rotateSpeed={0.5}
    />
  );
}

/* 🔹 Advanced lighting setup with shadows */
/* 🔹 Advanced lighting setup with anti-flickering */
function Lighting() {
  return (
    <>
      {/* Ambient light for base illumination */}
      <ambientLight intensity={0.4} />

      {/* Main directional light (sun) with optimized shadow settings */}
      <directionalLight
        position={[20, 20, -40]}
        intensity={1.5}
        castShadow
        shadow-mapSize={[4096, 4096]} // Higher quality
        shadow-camera-left={-50}
        shadow-camera-right={50}
        shadow-camera-top={50}
        shadow-camera-bottom={-50}
        shadow-camera-near={0.5} // Adjusted
        shadow-camera-far={100}
        shadow-bias={-0.0005} // KEY: Fixes shadow acne
        shadow-normalBias={0.02} // KEY: Additional fix
        shadow-radius={2} // Softer shadows
      />

      {/* Fill light from opposite side */}
      <directionalLight position={[-5, 10, -5]} intensity={0.5} />

      {/* Hemisphere light */}
      <hemisphereLight
        skyColor="#ffffff"
        groundColor="#444444"
        intensity={0.6}
      />
    </>
  );
}

/* 🔹 Floor renderer — key forces full unmount/remount on floor change */
function FloorModel({ floor }) {
  // Ensure all models receive and cast shadows
  const modelProps = {
    castShadow: true,
    receiveShadow: true,
  };

  switch (floor) {
    case "Main":
      return <Model key="main" {...modelProps} />;
    case "one":
      return <One key="one" {...modelProps} />;
    case "two":
      return <Two key="two" {...modelProps} />;
    case "three":
      return <Three key="three" {...modelProps} />;
    default:
      return <Model key="main" {...modelProps} />;
  }
}

export default function ModelViewer() {
  const [floor, setFloor] = useState("Main");

  const btnClass = (name) =>
    `font-semibold border rounded-xl p-2 m-2 text-center cursor-pointer select-none transition-all duration-200 ${
      floor === name
        ? "bg-green-400 text-black shadow-lg scale-105"
        : "bg-black text-white hover:bg-gray-800"
    }`;

  return (
    <div className="h-full md:h-2/3 lg:h-[75vh] w-full relative">
      <Canvas
        camera={{ fov: 50 }}
        className="rounded-xl shadow-xl"
        style={{ touchAction: "none" }}
        shadows="soft" // Use soft shadows instead of basic
        dpr={[1, 2]} // Pixel ratio for retina displays
        gl={{
          antialias: true,
          alpha: false,
          powerPreference: "high-performance",
          stencil: false, // Performance boost
          depth: true,
          logarithmicDepthBuffer: true, // KEY: Reduces z-fighting
        }}
        frameloop="demand" // Only render when needed (optional)
      >
        {/* Camera */}
        <CameraSetup />

        {/* Enhanced Lighting */}
        <Lighting />

        {/* Model with shadow support */}
        <FloorModel floor={floor} />

        {/* Ground shadow (soft, realistic) */}
        <ContactShadows
          position={[0, 0.01, 0]} // Slightly above ground
          opacity={0.4} // Reduced opacity
          scale={100}
          blur={2.5} // More blur = smoother
          far={20}
          resolution={512} // Add resolution
          color="#000000"
        />

        {/* Optional: Ground plane to receive shadows */}
        {/* Ground plane - positioned slightly lower */}
        <mesh
          rotation={[-Math.PI / 2, 0, 0]}
          position={[0, -0.1, 0]} // Moved down from -0.01 to -0.1
          receiveShadow
        >
          <planeGeometry args={[200, 200]} />
          <shadowMaterial transparent opacity={0.4} />
        </mesh>

        {/* Sky background (optional) */}
        <Sky
          distance={450000}
          sunPosition={[10, 20, 5]}
          inclination={0.6}
          azimuth={0.25}
        />

        {/* Controls */}
        <Controls />

        {/* Environment lighting */}
        <Environment preset="city" />
      </Canvas>
      {/* Instructions */}
      <div className="absolute top-2 left-2 flex flex-col w-full lg:w-96 justify-center items-center rounded-md bg-white/10 backdrop-blur-sm p-1">
        ☝️ 1本指：回転 &nbsp;|&nbsp; ✌️ 2本指：移動 &nbsp;|&nbsp; 🤏
        ピンチ：ズーム
        <div style={{ marginTop: 4 }}>
          モデルがロードまで少々お待ちください。出て来てない場合はリフレッシュして下さい。
        </div>
        <div style={{ marginTop: 4 }}>
          自分で作ったので、一部の機能がうまく動作しない可能性があります
        </div>
      </div>

      {/* Floor buttons with improved styling */}
      <div className="absolute right-2 bottom-2 flex flex-col w-24 justify-center items-center rounded-md bg-white/10 backdrop-blur-sm p-1">
        <div onClick={() => setFloor("three")} className={btnClass("three")}>
          ３階
        </div>
        <div onClick={() => setFloor("two")} className={btnClass("two")}>
          ２階
        </div>
        <div onClick={() => setFloor("one")} className={btnClass("one")}>
          １階
        </div>
        <div onClick={() => setFloor("Main")} className={btnClass("Main")}>
          建物
        </div>
      </div>
    </div>
  );
}
